import{_ as o,o as r,c as n,ak as a,j as t}from"./chunks/framework.CgPtPwGR.js";const i="/projects/Ackermann-Chassis/en/latest/assets/image2.BgTBLg4D.webp",s="/projects/Ackermann-Chassis/en/latest/assets/image3.BJdAJGz9.webp",l="/projects/Ackermann-Chassis/en/latest/assets/image4.BjoIyDTe.webp",w=JSON.parse('{"title":"1. Introduction & Installation","description":"","frontmatter":{},"headers":[],"relativePath":"docs/1_Introduction_Installation_checked.md","filePath":"docs/1_Introduction_Installation_checked.md"}'),c={name:"docs/1_Introduction_Installation_checked.md"};function h(d,e,u,p,m,g){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="_1-introduction-installation" tabindex="-1">1. Introduction &amp; Installation <a class="header-anchor" href="#_1-introduction-installation" aria-label="Permalink to &quot;1. Introduction &amp; Installation&quot;">​</a></h1><h2 id="_1-1-ackermann-chassis-introduction" tabindex="-1">1.1 Ackermann Chassis Introduction <a class="header-anchor" href="#_1-1-ackermann-chassis-introduction" aria-label="Permalink to &quot;1.1 Ackermann Chassis Introduction&quot;">​</a></h2><h3 id="_1-1-1-product-introduction" tabindex="-1">1.1.1 Product Introduction <a class="header-anchor" href="#_1-1-1-product-introduction" aria-label="Permalink to &quot;1.1.1 Product Introduction&quot;">​</a></h3><img loading="lazy" height="234" width="642" src="'+i+'" class="common_img"><p>The Ackermann steering chassis represents a standard configuration extensively employed in the new energy market and is a popular choice within the realm of autonomous driving. Specifically developed by Hiwonder, for educational scenarios, this Ackermann car chassis aligns with the standard structure of modern car chassis. In this design, the rear wheels consistently maintain a parallel orientation, while the inner wheels articulate at an angle during turns. Ackermann steering is characterized by the inner wheel turning at a greater angle than the outer wheel, and the disparity in turning angles is termed Ackermann steering.</p><p>This chassis employs the forward Ackermann steering structure, and the rear wheels are driven with electronic differential speed. This feature serves to enhance users&#39; comprehension of robots equipped with Ackermann steering structures. To validate these claims, further verification is recommended.</p><p>Key features of the Ackermann chassis include:</p><ul><li><strong>Easy Disassembly and Modification</strong></li></ul><p>(1) The chassis features a double-layer structure design with a bottom layer designed for battery installation.</p><p>(2) Numerous <code>M3</code> and <code>M4</code> installation holes are strategically placed, allowing for the installation of various components such as Raspberry Pi, microcontrollers, control systems, Lidar, depth cameras, sensors, and robotic arms.</p><ul><li><strong>High Steering Precision and Reliable Movement</strong></li></ul><p>(1) The steering structure employs high-precision components and is equipped with precision bearings, ensuring both accuracy and strong load-bearing capacity.</p><p>(2) Enhanced steering power is provided by a 15KG high-torque digital servo.</p><p>(3) The Ackermann chassis utilizes high-quality plastic tire treads, offering dense, large friction for a robust grip, anti-skid properties, and precise and reliable car movement.</p><ul><li><strong>Strong Driving Ability</strong></li></ul><p>(1) Equipped with a high-performance DC reduction motor featuring its own high-precision encoder.</p><p>(2) The motor operates at a rated voltage of 12V, delivering strong horsepower and excellent performance.</p><p>In conjunction with this course, participants will gain insights into:</p><ul><li><strong>The assembly of accessories required for car assembly.</strong></li></ul><p>(1) Connection methods between various components.</p><p>(2) Programming skills to control the movement of the car chassis using different main control boards.</p><p>(3) Understanding the software and hardware connections involved in the process.</p><h3 id="_1-1-2-ackermann-hardware-introduction" tabindex="-1">1.1.2 Ackermann Hardware Introduction <a class="header-anchor" href="#_1-1-2-ackermann-hardware-introduction" aria-label="Permalink to &quot;1.1.2 Ackermann Hardware Introduction&quot;">​</a></h3><ul><li><strong>Hardware Structure</strong></li></ul><p>The front wheel transmission system of the Ackerman chassis consists of a steering gear, connecting rod, and wheel. The steering gear is linked to the connecting rod, and the connecting rod is connected to the wheel. By rotating the steering gear, the rotation amplitude of the connecting rod is controlled, consequently managing the steering of the front wheel.</p><p>During turns, the two front wheels maintain a parallel alignment, meaning they rotate at the same angle. The control of the rear wheels involves motors and wheels. The robot&#39;s forward, backward, and speed movements are regulated by the motor&#39;s rotation.</p><img loading="lazy" height="390" width="555" src="'+s+'" class="common_img"><p>The Ackerman car is equipped with a 520 Hall-coded DC reduction motor—a high-torque, high-load motor with a 12V DC power supply and a reduction ratio of 1:30. This motor design enhances the performance and efficiency of the Ackerman chassis.</p><img loading="lazy" height="497" width="687" src="'+l+'" class="common_img"><ul><li><strong>Physical Characteristic</strong></li></ul><p>The Ackermann chassis is crafted with the goal of optimizing steering performance and stability. This design enhances the vehicle&#39;s controllability during cornering while minimizing sideslip when making turns.</p><p>Furthermore, the Ackermann chassis takes into account the positioning of the vehicle&#39;s center of gravity. The location of the center of gravity significantly influences the vehicle&#39;s stability and handling performance. Generally, Ackermann chassis designs incorporate a lower center of gravity to mitigate the risk of pitching and skidding, thereby enhancing overall safety and control.</p><h3 id="_1-1-3-development-tutorials-description" tabindex="-1">1.1.3 Development Tutorials Description <a class="header-anchor" href="#_1-1-3-development-tutorials-description" aria-label="Permalink to &quot;1.1.3 Development Tutorials Description&quot;">​</a></h3><p>The development tutorials are edited based on different controllers, including <code>Arduino Uno</code>, <code>STM32</code> controller, and <code>Raspberry Pi 4B</code>. You can select the appropriate course based on your specific controller.</p><h2 id="_1-2-double-layer-board-installation-tutorial" tabindex="-1">1.2 Double-layer board installation tutorial <a class="header-anchor" href="#_1-2-double-layer-board-installation-tutorial" aria-label="Permalink to &quot;1.2 Double-layer board installation tutorial&quot;">​</a></h2><h3 id="_1-2-1-double-layer-board-installation-tutorial" tabindex="-1">1.2.1 Double-layer board installation tutorial <a class="header-anchor" href="#_1-2-1-double-layer-board-installation-tutorial" aria-label="Permalink to &quot;1.2.1 Double-layer board installation tutorial&quot;">​</a></h3><p>Greetings, everyone! In today&#39;s video, I&#39;ll guide you through the step-by-step assembly process of the double-layer Ackermann chassis. Let&#39;s dive in! Begin by removing the four screws. Here&#39;s a helpful tip: hold the column with your hand to keep the bottom screw secure. Next, attach the single-pass copper column to these designated holes. Moving on, affix the second layer onto the columns and secure them together using screws. And there you have it – assembly is complete! For details on wiring and controller installation, please check out the next video.</p><h3 id="_1-2-2-ackermann-chassis-controller-and-wiring-instructions" tabindex="-1">1.2.2 Ackermann chassis controller and wiring instructions <a class="header-anchor" href="#_1-2-2-ackermann-chassis-controller-and-wiring-instructions" aria-label="Permalink to &quot;1.2.2 Ackermann chassis controller and wiring instructions&quot;">​</a></h3><p>Hello everyone. In this video, I&#39;ll demonstrate how to install the <code>STM32</code> controller onto the Ackermann chassis. Before installation, ensure to pass this wire through the designated hole for future wiring purposes. Now, let&#39;s proceed with the <code>STM32</code> controller installation. Align the four holes on the controller with those on the chassis. Next, attach four columns to the corresponding holes on the chassis using nuts. Then, secure the controller onto these columns using screws. It&#39;s important to note that the four motor interfaces on the <code>STM32</code> controller should face towards the rear of the car. Now, connect the wire from the servo that controls the steering of the front wheels to the third row of pins (<code>J1</code>) on the controller. Be sure to connect it to the correct terminal. Next, connect the right rear wheel to the <code>M1</code> port and the left rear wheel to the <code>M2</code> port. Great! The installation and wiring of the controller are now complete.</p><h3 id="_1-2-3-battery-installation" tabindex="-1">1.2.3 Battery Installation <a class="header-anchor" href="#_1-2-3-battery-installation" aria-label="Permalink to &quot;1.2.3 Battery Installation&quot;">​</a></h3><p>Hello everyone. In this video, I&#39;ll demonstrate how to connect the battery to the controller. The &#39;+&#39; symbol represents the positive power electrode, while the &#39;-&#39; symbol denotes the negative power electrode. Start by passing the battery wire through this designated hole, then use a screwdriver to loosen the screw of the power terminal. Next, connect the black wire to the negative terminal and the red wire to the positive terminal. Once done, prepare the hook and loop to securely attach the battery to the car chassis. Then, connect the connector ensuring the red wire aligns with the red wire, and the black wire aligns with the black wire. The plug features an anti-reverse plug-in design, so avoid forcefully plugging them in. It&#39;s crucial not to connect the connector before attaching the battery wire to the power terminal of the controller, as this could result in a short circuit.</p><h3 id="_1-2-4-introduction-to-hardware-required-for-raspberry-pi-development" tabindex="-1">1.2.4 Introduction to hardware required for Raspberry Pi development <a class="header-anchor" href="#_1-2-4-introduction-to-hardware-required-for-raspberry-pi-development" aria-label="Permalink to &quot;1.2.4 Introduction to hardware required for Raspberry Pi development&quot;">​</a></h3><p>Hello, everyone! Welcome to this video where I&#39;ll guide you through the components required for <code>Raspberry Pi</code> development. Let&#39;s start by examining the Ackermann chassis. These two rear wheels are responsible for driving the chassis forward and backward. The <code>6PIN</code> motor wire attached to them will be detailed in our next video on connecting them to the <code>Raspberry Pi</code>.</p><p>Additionally, we have a <code>PWM</code> servo used to steer the front wheels. Again, we&#39;ll cover the wiring method for this in our upcoming video.</p><p>For power, we&#39;ll be using an 11.1V Lithium battery. You&#39;ll also need three female-to-male Dupont wires for connecting the <code>PWM</code> servo to the <code>Raspberry Pi</code>, and three female-to-female DuPont wires for <code>IIC</code> communication between the motor driver and <code>Raspberry Pi</code>.</p><p>Of course, you&#39;ll need a <code>Raspberry Pi</code>. Remember to write the system image provided into the SD card and insert it into the <code>Raspberry Pi</code>. Instructions for writing the system image can be found in the provided tutorial.</p><p>To ensure sufficient power for the <code>Raspberry Pi</code> components, connect a power bank to the <code>type-C</code> port for power supply.</p><p>Now, onto the motor driver. It&#39;s important to note that you&#39;ll need to solder the four pins yourself. The battery wire is already attached to the driver, allowing you to connect the battery easily. You can also supply power to the motor driver through the provided port. Simply connect the power source&#39;s positive and negative terminals to this port. It&#39;s essential to use separate power supplies for the <code>Raspberry Pi</code> and the motor driver.</p><p>Finally, make sure to have the necessary screw accessories on hand for assembly. Stay tuned for more detailed instructions on wiring and assembly in our upcoming videos!</p><h2 id="_1-3-double-layer-version-installation" tabindex="-1">1.3 Double-Layer Version Installation <a class="header-anchor" href="#_1-3-double-layer-version-installation" aria-label="Permalink to &quot;1.3 Double-Layer Version Installation&quot;">​</a></h2>',50),t("p",null,[t("iframe",{width:"100%",height:"713",src:"https://www.youtube.com/embed/8mtxbLwPIhk",title:"Ackermann Chassis--Double Layer Version Installation",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""})],-1)])])}const y=o(c,[["render",h]]);export{w as __pageData,y as default};
